import{_ as a,o as r,c as n,j as e,a as o}from"./chunks/framework.UjrY2eRK.js";const u=JSON.parse('{"title":"Maintain one contract across deployment targets","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0015-maintain-one-contract-across-deployment-targets.md","filePath":"architecture/adr/0015-maintain-one-contract-across-deployment-targets.md","lastUpdated":1788123021000}'),s={name:"architecture/adr/0015-maintain-one-contract-across-deployment-targets.md"};function i(c,t,l,d,p,m){return r(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"maintain-one-contract-across-deployment-targets",tabindex:"-1"},[o("Maintain one contract across deployment targets "),e("a",{class:"header-anchor",href:"#maintain-one-contract-across-deployment-targets","aria-label":'Permalink to "Maintain one contract across deployment targets"'},"​")],-1),e("p",null,"The gateway will have one runtime-neutral core with first-class adapters for Cloudflare Workers with D1 and self-hosted Bun with SQLite. Both targets must preserve the same Matrix API, FCM behavior, privacy rules, retry coordination, and safety limits; Cloudflare remains the default zero-cost deployment, while self-hosting supports one Bun service instance with one local persistent SQLite database behind an external TLS proxy. Each deployment remains single-tenant for one compatible app operator, and release merges publish hardened versioned Docker images for AMD64 and ARM64 alongside the existing Worker release.",-1),e("p",null,"Horizontal replicas, network-hosted SQLite files, built-in TLS termination, and Trinity client development are outside this decision. Supporting those capabilities later requires a new storage or deployment design rather than runtime-specific behavior in the shared gateway core.",-1)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
